def validate_activation(activation: dict, root: Path = ROOT, verify_sources: bool = False) -> list[str]:
    """Hard-stop on a broad or forged G6 transition. Only the audited packet is authorized."""
    spec = activation_spec(activation)
    if spec is None:
        return ["activation selected packet is not an audited G6 packet"]
    expected, sources, pinned, extra_keys = spec
    errors = []
    if set(activation) != set(expected) | extra_keys:
        errors.append("activation keys must match exactly one audited G6 packet")
    for key, value in expected.items():
        if activation.get(key) != value:
            errors.append(f"activation {key} mismatch: no bulk owner authority")
    if "gate_pr" in extra_keys:
        gate_pr = activation.get("gate_pr")
        if not isinstance(gate_pr, int) or gate_pr < 0:
            errors.append("activation gate_pr must be a non-negative integer")
    if "sdl3" in extra_keys:
        expected_sdl3 = {
            "version": "3.4.20",
            "repository": "https://github.com/libsdl-org/SDL.git",
            "commit": "f00dc919ca35b9756316e86c4777392de442f9b2",
            "license": "zlib",
            "linkage": "static",
            "build_time_fetch": True,
        }
        if activation.get("sdl3") != expected_sdl3:
            errors.append("activation SDL3 pin mismatch: only static 3.4.20 at the exact commit is authorized")
    if "window_slice" in extra_keys:
        expected_window_slice = {
            "linux_drivers_built": ["x11", "wayland"],
            "linux_runtime_tested": "x11",
            "linux_runtime_not_qualified": "wayland",
            "windows_runtime": "win32",
            "macos_runtime": "cocoa_or_not_qualified",
            "linux_display": "xvfb+openbox",
            "render_gpu_audio": "disabled",
            "linux_packages": [
                "libx11-dev",
                "libxext-dev",
                "libxrandr-dev",
                "libxcursor-dev",
                "libxfixes-dev",
                "libxi-dev",
                "libxss-dev",
                "libxtst-dev",
                "libxinerama-dev",
                "libxrender-dev",
                "libxkbcommon-dev",
                "libxkbcommon-x11-dev",
                "libwayland-dev",
                "libdecor-0-dev",
                "wayland-protocols",
                "libdbus-1-dev",
                "libibus-1.0-dev",
                "libthai-dev",
                "libfribidi-dev",
                "libgl1-mesa-dev",
                "libegl1-mesa-dev",
                "libgles2-mesa-dev",
                "xvfb",
                "x11-utils",
                "openbox",
            ],
        }
        if activation.get("window_slice") != expected_window_slice:
            errors.append("activation window slice mismatch: only the exact X11/Win32/Cocoa install matrix is authorized")
    if "capability_admission" in extra_keys:
        selected_id = str(activation.get("selected_packet_id", ""))
        if selected_id.startswith("NLE-PRPLAN-WORLD-02-"):
            expected_admission = WORLD02_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-WORLD-01-"):
            expected_admission = WORLD01_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-TWO-04-"):
            expected_admission = TWO04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-TWO-03-"):
            expected_admission = TWO03_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-TWO-02-"):
            expected_admission = TWO02_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-TWO-01-"):
            expected_admission = TWO01_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-08-"):
            expected_admission = GFX08_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-07-"):
            expected_admission = GFX07_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-06-"):
            expected_admission = GFX06_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-05-"):
            expected_admission = GFX05_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-04-"):
            expected_admission = GFX04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-03-"):
            expected_admission = GFX03_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-02-"):
            expected_admission = GFX02_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-GFX-01-"):
            expected_admission = GFX01_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-DATA-05-"):
            expected_admission = DATA05_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-DATA-04-"):
            expected_admission = DATA04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-DATA-03-"):
            expected_admission = DATA03_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-DATA-02-"):
            expected_admission = DATA02_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-DATA-01-"):
            expected_admission = CORE04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-CORE-06-"):
            expected_admission = CORE04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-CORE-05-"):
            expected_admission = CORE04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-CORE-04-"):
            expected_admission = CORE04_CAPABILITY_ADMISSION
        elif selected_id.startswith("NLE-PRPLAN-CORE-03-"):
            expected_admission = CORE03_CAPABILITY_ADMISSION
        else:
            expected_admission = CORE02_CAPABILITY_ADMISSION
        if activation.get("capability_admission") != expected_admission:
            errors.append("activation capability admission mismatch: only the exact audited set is authorized")
    fingerprints = activation.get("source_blob_sha1")
    if not isinstance(fingerprints, dict) or set(fingerprints) != set(sources):
        errors.append("activation source_blob_sha1 must contain exactly the pinned sources")
    elif fingerprints != pinned:
        errors.append("activation source fingerprints do not match approved baseline")
    elif verify_sources:
        errors.extend(verify_source_blobs(fingerprints, root, sources))
    return errors


